export const getGetFacilityAvailabilityUrl = (id: number,
    params: GetFacilityAvailabilityParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/facilities/${id}/availability?${stringifiedParams}` : `/api/facilities/${id}/availability`
}

